type appWhere[Q sqlite.Filterable] struct {
	cols           appColumns
	ID             sqlite.WhereMod[Q, string]
	CreatedAt      sqlite.WhereMod[Q, time.Time]
	UpdatedAt      sqlite.WhereMod[Q, time.Time]
	WorkspaceID    sqlite.WhereMod[Q, string]
	Key            sqlite.WhereMod[Q, string]
	Name           sqlite.WhereMod[Q, string]
	Description    sqlite.WhereMod[Q, string]
	State          sqlite.WhereMod[Q, string]
	Parameters     sqlite.WhereMod[Q, types.JSON[model.JSONMap]]
	CurrentVersion sqlite.WhereMod[Q, int64]
	CreatedBy      sqlite.WhereMod[Q, string]
	UpdatedBy      sqlite.WhereMod[Q, string]
	Version        sqlite.WhereMod[Q, int64]
	R              appWhereR[Q]
}

func (appWhere[Q]) AliasedAs(alias string) appWhere[Q] {
	return buildAppWhere[Q](buildAppColumns(alias))
}

func buildAppWhere[Q sqlite.Filterable](cols appColumns) appWhere[Q] {
	return appWhere[Q]{
		cols:           cols,
		ID:             sqlite.Where[Q, string](cols.ID.Expression),
		CreatedAt:      sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:      sqlite.Where[Q, time.Time](cols.UpdatedAt.Expression),
		WorkspaceID:    sqlite.Where[Q, string](cols.WorkspaceID.Expression),
		Key:            sqlite.Where[Q, string](cols.Key.Expression),
		Name:           sqlite.Where[Q, string](cols.Name.Expression),
		Description:    sqlite.Where[Q, string](cols.Description.Expression),
		State:          sqlite.Where[Q, string](cols.State.Expression),
		Parameters:     sqlite.Where[Q, types.JSON[model.JSONMap]](cols.Parameters.Expression),
		CurrentVersion: sqlite.Where[Q, int64](cols.CurrentVersion.Expression),
		CreatedBy:      sqlite.Where[Q, string](cols.CreatedBy.Expression),
		UpdatedBy:      sqlite.Where[Q, string](cols.UpdatedBy.Expression),
		Version:        sqlite.Where[Q, int64](cols.Version.Expression),
		R:              appWhereR[Q]{cols: cols},
	}
}

// appWhereR holds the relationship-based filters of
// appWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type appWhereR[Q sqlite.Filterable] struct {
	cols appColumns
}

// HasAppVersions filters parents that have a matching AppVersions using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to AppVersions).
func (w appWhereR[Q]) HasAppVersions(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(AppVersions.NameExpr()),
		sm.Where(AppVersions.Columns.AppID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

// HasWorkspaceResource filters parents that have a matching WorkspaceResource using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Resources).
func (w appWhereR[Q]) HasWorkspaceResource(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(Resources.NameExpr()),
		sm.Where(Resources.Columns.ID.EQ(w.cols.WorkspaceID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}
